def solve():
    results = []
    for n in range(1, 5000):
        b = []
        temp_n = n
        while temp_n > 0:
            b.append(temp_n % 7)
            temp_n //= 7
        m_val = 0
        for i, digit in enumerate(b):
            m_val += digit * (10**i)

        m_base7 = []
        temp_m = m_val
        if temp_m == 0:
            m_base7 = [0]
        else:
            while temp_m > 0:
                m_base7.append(temp_m % 7)
                temp_m //= 7

        sum_a = 0
        for i in range(len(b)):
            target = b[i]
            idx = -1
            for j in range(len(m_base7)):
                if m_base7[j] == target:
                    idx = j
                    break
            if idx != -1:
                new_m_digits = m_base7[:idx] + m_base7[idx+1:]
                a_i = 0
                for j, digit in enumerate(new_m_digits):
                    a_i += digit * (7**j)
                sum_a += a_i
            else:
                sum_a += m_val

        if sum_a == n:
            results.append((n, b, m_val, m_base7))

    return results

